#!/usr/bin/env python3
"""生成 files/etc/uci-defaults/99-ponwrt-defaults，把默认时区与 root 密码固化进固件。

由 GitHub Actions 在编译前调用（build-ponwrt.yml / release.yml）。生成的
uci-defaults 脚本在首次启动时应用；sysupgrade 保留配置升级后也会重新施加
固件默认值。

环境变量：
  PONWRT_TIMEZONE       IANA 时区名（如 Asia/Shanghai）或 POSIX TZ 串（如 CST-8）；空 = UTC
  PONWRT_ROOT_PASSWORD  默认 root 密码；空 = 保持无密码（OpenWrt 出厂行为）
"""

import os
import pathlib

TIMEZONE = os.environ.get("PONWRT_TIMEZONE", "").strip() or "UTC"
PASSWORD = os.environ.get("PONWRT_ROOT_PASSWORD", "").replace("\r", "").replace("\n", "")

# 常用 IANA 时区 → POSIX TZ 串（无 DST 地区为主）；不在表中的 IANA 名称回退 UTC
POSIX_MAP = {
    "Asia/Shanghai": "CST-8",
    "Asia/Urumqi": "CST-8",
    "Asia/Taipei": "CST-8",
    "Asia/Hong_Kong": "HKT-8",
    "Asia/Macau": "CST-8",
    "Asia/Singapore": "SGT-8",
    "Asia/Tokyo": "JST-9",
    "Asia/Seoul": "KST-9",
    "Asia/Bangkok": "ICT-7",
    "Asia/Kolkata": "IST-5:30",
    "Asia/Dubai": "GST-4",
    "UTC": "UTC",
    "Etc/UTC": "UTC",
}

if "/" in TIMEZONE:
    zonename = TIMEZONE
    posix = POSIX_MAP.get(TIMEZONE, "UTC")
else:
    posix = TIMEZONE
    zonename = "UTC" if posix == "UTC" else posix

lines = [
    "#!/bin/sh",
    "# Generated by .github/scripts/firmware-defaults.py at build time.",
    f"uci -q set system.@system[0].zonename='{zonename}'",
    f"uci -q set system.@system[0].timezone='{posix}'",
    "uci -q commit system",
]
if PASSWORD:
    # 单引号安全转义；busybox passwd 两次读取密码之间需要间隔
    quoted = PASSWORD.replace("'", "'\"'\"'")
    lines += [
        "",
        f"(echo '{quoted}'; sleep 1; echo '{quoted}') | passwd root >/dev/null 2>&1 || true",
    ]
lines.append("exit 0")

path = pathlib.Path("files/etc/uci-defaults/99-ponwrt-defaults")
path.parent.mkdir(parents=True, exist_ok=True)
path.write_text("\n".join(lines) + "\n")

print(f"firmware defaults: timezone={zonename} ({posix}), "
      + ("root password=set" if PASSWORD else "root password=empty (stock)"))
